import { ASSETS, assetValue } from "./assets/assets.js"; import { CRAB_MINING_CONFIG } from "./config/crabMining.js"; import { createOpeningLoop } from "./hooks/openingLoop.js"; import { showScreen, wireLoginModes } from "./screens/screens.js"; import { createCrabClickController } from "./state/crabClickState.js"; function requireElement(selector) { const element = document.querySelector(selector); if (!element) { throw new Error(`Missing required element: ${selector}`); } return element; } const elements = { openingScreen: requireElement("#openingScreen"), loginScreen: requireElement("#loginScreen"), characterScreen: requireElement("#characterScreen"), miningScreen: requireElement("#miningScreen"), opening01: requireElement("#opening01"), opening02: requireElement("#opening02"), openingLogoButton: requireElement("#openingLogoButton"), loginForm: requireElement("#loginForm"), forgotButton: requireElement("#forgotButton"), passwordField: requireElement("#passwordField"), signupButton: requireElement("#signupButton"), signupCopy: requireElement("#signupCopy"), twitchLoginButton: requireElement("#twitchLoginButton"), characterVideo: requireElement("#characterVideo"), diveInButton: requireElement("#diveInButton"), sayHiVideo: requireElement("#sayHiVideo"), idleVideo: requireElement("#idleVideo"), miningActionVideo: requireElement("#miningActionVideo"), mineButton: requireElement("#mineButton"), tapFeedback: requireElement("#tapFeedback"), totalMined: requireElement("#totalMined"), srStatus: requireElement("#srStatus") }; const screens = { opening: elements.openingScreen, login: elements.loginScreen, character: elements.characterScreen, mining: elements.miningScreen }; const animationState = { current: "sayHi", isMiningActive: false, pendingMiningReplay: false }; let totalMined = 12450; const crabClickController = createCrabClickController(); function setStatus(message) { elements.srStatus.textContent = message; } function applyAssets() { document.querySelectorAll("[data-asset]").forEach((element) => { const value = assetValue(element.dataset.asset); if (!value) return; element.src = value; }); elements.opening01.src = ASSETS.opening01; elements.opening02.src = ASSETS.opening02; elements.characterVideo.src = ASSETS.characterCrab; prepareVideo(elements.sayHiVideo, ASSETS.crabSayHi, { loop: false }); prepareVideo(elements.idleVideo, ASSETS.crabIdle); prepareVideo(elements.miningActionVideo, ASSETS.crabMining, { loop: false }); } function prepareVideo(video, src, { loop = true } = {}) { video.loop = loop; video.muted = true; video.playsInline = true; video.preload = "auto"; if (!video.currentSrc.endsWith(src)) { video.src = src; video.load(); } } function logVideoSwitch(next, video) { console.log("[Tachigo video switch]", { next, src: video.currentSrc || video.src, readyState: video.readyState, paused: video.paused, currentTime: video.currentTime }); } function playVideo(video, src, { loop = true, restart = true } = {}) { prepareVideo(video, src, { loop }); if (restart) { try { video.currentTime = 0; } catch { } } video.play().catch(() => setStatus("Tap the screen to start playback.")); } function showTapFeedback(text, className = "") { elements.tapFeedback.textContent = text; elements.tapFeedback.className = "tap-feedback"; if (className) elements.tapFeedback.classList.add(className); void elements.tapFeedback.offsetWidth; elements.tapFeedback.classList.add("is-visible"); } function setActiveMiningVideo(activeVideo, next) { [elements.sayHiVideo, elements.idleVideo, elements.miningActionVideo].forEach((video) => { video.classList.toggle("is-active", video === activeVideo); if (video !== activeVideo) video.pause(); }); logVideoSwitch(next, activeVideo); } function playWhenReady(video, next, { restart = true } = {}) { const start = () => { if (restart) { try { video.currentTime = 0; } catch { } } setActiveMiningVideo(video, next); video.play().catch((error) => { console.warn("[Tachigo video play failed]", next, error); setStatus("Tap the screen to start playback."); }); }; if (video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) { start(); return; } video.addEventListener("canplay", start, { once: true }); video.load(); } function switchToSayHi() { animationState.current = "sayHi"; animationState.isMiningActive = false; animationState.pendingMiningReplay = false; elements.mineButton.disabled = true; prepareVideo(elements.sayHiVideo, ASSETS.crabSayHi, { loop: false }); prepareVideo(elements.idleVideo, ASSETS.crabIdle); prepareVideo(elements.miningActionVideo, ASSETS.crabMining, { loop: false }); playWhenReady(elements.sayHiVideo, "sayHi"); setStatus("Crab says hi."); } function switchToIdle() { animationState.current = "idle"; animationState.isMiningActive = false; elements.mineButton.disabled = false; prepareVideo(elements.idleVideo, ASSETS.crabIdle); playWhenReady(elements.idleVideo, "idle"); setStatus("Crab is idle."); } function triggerMiningAnimation() { if (animationState.current === "mining") { animationState.pendingMiningReplay = true; return; } animationState.current = "mining"; animationState.isMiningActive = true; animationState.pendingMiningReplay = false; prepareVideo(elements.miningActionVideo, ASSETS.crabMining, { loop: false }); playWhenReady(elements.miningActionVideo, "mining"); } function goToLogin() { openingLoop.stop(); showScreen(screens, "login"); setStatus("Login screen."); } function goToCharacter() { showScreen(screens, "character"); playVideo(elements.characterVideo, ASSETS.characterCrab); setStatus("Choose your character."); } function goToMining() { elements.characterVideo.pause(); showScreen(screens, "mining"); switchToSayHi(); } function mine() { const clickResult = crabClickController.registerClick(); if (!clickResult.valid) { showTapFeedback("MAX", "is-invalid"); setStatus("Invalid click. Crab click quota reached for this tick."); return; } totalMined += clickResult.pointGain; elements.totalMined.textContent = totalMined.toLocaleString("en-US"); triggerMiningAnimation(); showTapFeedback(clickResult.burstTriggered ? `x${clickResult.burstMultiplier}` : `+${clickResult.pointGain}`); const quota = `${clickResult.state.validClicksThisTick}/${CRAB_MINING_CONFIG.maxValidClicksPerTick}`; setStatus(`Valid crab click. ${quota} clicks this tick. ${clickResult.state.comboState} combo, ${clickResult.continuousMultiplier}x multiplier.`); } applyAssets(); const openingLoop = createOpeningLoop({ opening01: elements.opening01, opening02: elements.opening02, onStatus: setStatus }); elements.openingLogoButton.addEventListener("click", goToLogin); wireLoginModes( { forgotButton: elements.forgotButton, form: elements.loginForm, passwordField: elements.passwordField, signupButton: elements.signupButton, signupCopy: elements.signupCopy }, goToCharacter ); elements.twitchLoginButton.addEventListener("click", goToCharacter); elements.diveInButton.addEventListener("click", goToMining); elements.mineButton.addEventListener("click", mine); elements.sayHiVideo.addEventListener("ended", () => { if (animationState.current === "sayHi") switchToIdle(); }); elements.miningActionVideo.addEventListener("ended", () => { if (animationState.current !== "mining") return; if (animationState.pendingMiningReplay) { animationState.pendingMiningReplay = false; playWhenReady(elements.miningActionVideo, "mining"); return; } switchToIdle(); }); const tickTimer = window.setInterval(() => { crabClickController.syncTickWindow(); }, 1000); window.addEventListener("pagehide", () => { openingLoop.stop(); window.clearInterval(tickTimer); }); openingLoop.start();
